from datetime import datetime, timezone
from decimal import Decimal, ROUND_DOWN
from typing import List, Union

from pydantic import BaseModel, Field, ValidationError, condecimal, conint, validator


class Line(BaseModel):
    sku: str
    quantity: conint(ge=1)
    unit_price: condecimal(ge=0, max_digits=20, decimal_places=2)

    @validator("unit_price", pre=True)
    def parse_unit_price(cls, v):
        # Accept str/int/float, convert to Decimal with 2 decimals exactly
        try:
            d = Decimal(str(v))
        except Exception:
            raise ValueError("unit_price must be a decimal number")
        # Quantize to 2 decimal places, rounding down to avoid rounding surprises
        d = d.quantize(Decimal("0.01"), rounding=ROUND_DOWN)
        if d < 0:
            raise ValueError("unit_price must be >= 0")
        return d


class Invoice(BaseModel):
    number: str
    issued_at: datetime
    lines: List[Line]

    class Config:
        # No orm_mode needed here
        arbitrary_types_allowed = True

    @validator("issued_at", pre=True)
    def parse_issued_at(cls, v):
        # Accept ISO 8601 string or datetime
        if isinstance(v, datetime):
            dt = v
        elif isinstance(v, str):
            try:
                dt = datetime.fromisoformat(v)
            except Exception:
                raise ValueError("issued_at must be a valid ISO 8601 datetime string or datetime")
        else:
            raise ValueError("issued_at must be a datetime or ISO 8601 string")
        # If naive, treat as UTC
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        # Remove microseconds for second precision
        dt = dt.replace(microsecond=0)
        return dt


def export_invoice(data: dict) -> str:
    """
    Validate an invoice dict and return JSON text for the billing API.
    Output JSON includes "number", "issued_at" formatted as YYYY-MM-DDTHH:MM:SSZ in UTC,
    "lines" with "sku", "quantity", "unit_price" as string with 2 decimals,
    and "total" as string with 2 decimals.
    Raises ValueError for invalid input.
    """
    try:
        invoice = Invoice.parse_obj(data)
    except ValidationError as e:
        raise ValueError(str(e)) from e

    # Compute total as Decimal sum of quantity * unit_price
    total = sum((line.quantity * line.unit_price for line in invoice.lines), Decimal("0.00"))
    # Format total as string with exactly two decimals
    total_str = f"{total:.2f}"

    # Format issued_at as YYYY-MM-DDTHH:MM:SSZ
    issued_at_str = invoice.issued_at.strftime("%Y-%m-%dT%H:%M:%SZ")

    # Prepare lines with unit_price as string with 2 decimals
    lines_out = []
    for line in invoice.lines:
        lines_out.append({
            "sku": line.sku,
            "quantity": line.quantity,
            "unit_price": f"{line.unit_price:.2f}",
        })

    # Compose output dict
    out = {
        "number": invoice.number,
        "issued_at": issued_at_str,
        "lines": lines_out,
        "total": total_str,
    }

    # Return JSON text
    import json
    return json.dumps(out, separators=(",", ":"))

from pydantic import BaseModel, Field, root_validator, validator, ValidationError
import re


class SignupPayload(BaseModel):
    username: str = Field(..., regex=r"^[a-z0-9_]{3,20}$")
    email: str
    phone: str
    password: str = Field(..., min_length=8)
    password_confirm: str

    @validator("email")
    def email_must_contain_at(cls, v: str) -> str:
        v = v.strip().lower()
        if "@" not in v:
            raise ValueError("email must contain '@'")
        return v

    @validator("phone")
    def normalize_phone(cls, v: str) -> str:
        if not isinstance(v, str):
            raise TypeError("phone must be a string")
        compact = re.sub(r"[\s.\-()]", "", v)
        if not re.fullmatch(r"\+\d{8,15}", compact):
            raise ValueError("invalid phone number")
        return compact

    @root_validator
    def passwords_match(cls, values):
        pw = values.get("password")
        pwc = values.get("password_confirm")
        if pw is not None and pwc is not None and pw != pwc:
            raise ValueError("passwords do not match")
        return values


def validate_signup(data: dict) -> dict:
    """
    Validate a sign-up payload dict using pydantic.

    Returns a dict with keys: username, email (stripped and lowercased), phone (compact form).
    Raises ValueError (ValidationError) on invalid or missing fields.
    """
    validated = SignupPayload.parse_obj(data)
    return {
        "username": validated.username,
        "email": validated.email,
        "phone": validated.phone,
    }

from datetime import datetime, timezone
from decimal import Decimal, ROUND_DOWN, InvalidOperation
from typing import List

from pydantic import BaseModel, Field, ValidationError, field_validator


class Line(BaseModel):
    sku: str
    quantity: int = Field(..., ge=1)
    unit_price: Decimal = Field(..., ge=0)

    @field_validator("unit_price", mode="before")
    @classmethod
    def parse_unit_price(cls, v):
        # Accept str/int/float and convert to Decimal
        try:
            d = Decimal(v)
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError("unit_price must be a decimal >= 0")
        if d < 0:
            raise ValueError("unit_price must be >= 0")
        # Quantize to 2 decimal places without rounding up
        return d.quantize(Decimal("0.01"), rounding=ROUND_DOWN)


class Invoice(BaseModel):
    number: str
    issued_at: datetime
    lines: List[Line]

    @field_validator("issued_at", mode="before")
    @classmethod
    def parse_issued_at(cls, v):
        # Accept ISO 8601 string or datetime
        if isinstance(v, datetime):
            dt = v
        elif isinstance(v, str):
            try:
                dt = datetime.fromisoformat(v)
            except ValueError:
                raise ValueError("issued_at must be ISO 8601 datetime string or datetime")
        else:
            raise ValueError("issued_at must be ISO 8601 datetime string or datetime")
        # If naive, treat as UTC
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        # Remove microseconds for second precision
        dt = dt.replace(microsecond=0)
        return dt

    def model_dump_json(self, **kwargs):
        # Override to produce JSON with issued_at formatted as YYYY-MM-DDTHH:MM:SSZ
        # and unit_price as string with exactly two decimals
        import json

        def serialize(obj):
            if isinstance(obj, datetime):
                # Format as UTC ISO8601 with trailing Z
                return obj.strftime("%Y-%m-%dT%H:%M:%SZ")
            if isinstance(obj, Decimal):
                # Format Decimal with two decimals as string
                return f"{obj:.2f}"
            raise TypeError(f"Type {type(obj)} not serializable")

        d = self.model_dump()
        # Add total field as string with two decimals
        total = sum(line.quantity * line.unit_price for line in self.lines)
        d["total"] = f"{total.quantize(Decimal('0.01'), rounding=ROUND_DOWN):.2f}"
        return json.dumps(d, default=serialize, separators=(",", ":"))

def export_invoice(data: dict) -> str:
    """Validate invoice dict and return JSON text for billing API with total field."""
    try:
        invoice = Invoice.model_validate(data)
    except ValidationError as e:
        raise ValueError(e) from e
    return invoice.model_dump_json()

import re
from pydantic import BaseModel, Field, ValidationError, model_validator
from typing import Any


class PhoneNumber(str):
    """Phone number in international form: '+' followed by 8-15 digits.
    Spaces, dots, dashes and parentheses in the input are ignored."""

    @classmethod
    def __get_pydantic_core_schema__(cls, source, handler):
        # Use a plain string schema with custom validation
        from pydantic import core_schema

        def validate_phone(value: Any, _: core_schema.ValidationInfo) -> "PhoneNumber":
            if not isinstance(value, str):
                raise TypeError("phone number must be a string")
            compact = re.sub(r"[\s.\-()]", "", value)
            if not re.fullmatch(r"\+\d{8,15}", compact):
                raise ValueError("invalid phone number")
            return cls(compact)

        return core_schema.no_info_plain_validator_function(validate_phone)


class SignupForm(BaseModel):
    username: str = Field(pattern=r"^[a-z0-9_]{3,20}$")
    email: str
    phone: PhoneNumber
    password: str = Field(min_length=8)
    password_confirm: str

    model_config = dict(from_attributes=True)

    @model_validator(mode="before")
    @classmethod
    def normalize_email(cls, values: dict[str, Any]) -> dict[str, Any]:
        # Normalize email: must contain '@', strip and lower-case
        email = values.get("email")
        if email is None:
            return values
        if not isinstance(email, str):
            raise TypeError("email must be a string")
        email_stripped = email.strip().lower()
        if "@" not in email_stripped:
            raise ValueError("email must contain '@'")
        values["email"] = email_stripped
        return values

    @model_validator(mode="after")
    @classmethod
    def passwords_match(cls, model: "SignupForm") -> "SignupForm":
        if model.password != model.password_confirm:
            raise ValueError("passwords do not match")
        return model


def validate_signup(data: dict) -> dict:
    """
    Validate a sign-up payload with pydantic.
    Fields:
      - username: must match ^[a-z0-9_]{3,20}$
      - email: must contain '@', returned stripped and lower-cased
      - phone: spaces, dots, dashes, parentheses removed, must be '+' followed by 8-15 digits
      - password: at least 8 characters
      - password_confirm: must equal password
    Returns dict with keys: username, email, phone (compact form).
    Raises ValueError (pydantic.ValidationError) for any missing or invalid field.
    """
    form = SignupForm.model_validate(data)
    return {"username": form.username, "email": form.email, "phone": form.phone}
